def count_fires(spec: str, blackouts: list[tuple[int, int]], a: int, b: int) -> int:
    if b <= a:
        return 0

    minute_set, hour_set, weekday_set = _parse_spec(spec)
    fire_per_week = len(minute_set) * len(hour_set) * len(weekday_set)

    # Precompute prefix sums: PREFIX[t] = number of fire minutes in [0, t)
    PREFIX = [0] * 10081
    for t in range(10080):
        if t % 60 in minute_set and (t // 60) % 24 in hour_set and (t // 1440) % 7 in weekday_set:
            PREFIX[t + 1] = PREFIX[t] + 1
        else:
            PREFIX[t + 1] = PREFIX[t]

    def count_fire(n: int) -> int:
        """Count fire minutes in [0, n)."""
        return (n // 10080) * fire_per_week + PREFIX[n % 10080]

    # Total fire minutes in [a, b)
    total = count_fire(b) - count_fire(a)

    # Merge overlapping blackouts (clipped to [a, b))
    clipped = []
    for s, e in blackouts:
        s = max(s, a)
        e = min(e, b)
        if s < e:
            clipped.append((s, e))

    clipped.sort()
    merged = []
    for s, e in clipped:
        if not merged or merged[-1][1] < s:
            merged.append((s, e))
        else:
            merged[-1] = (merged[-1][0], max(merged[-1][1], e))

    # Subtract fire minutes in merged blackouts
    for s, e in merged:
        total -= count_fire(e) - count_fire(s)

    return total


def _parse_spec(spec: str) -> tuple[set[int], set[int], set[int]]:
    fields = spec.split()
    if len(fields) != 3:
        raise ValueError("Wrong number of fields")

    minute_spec, hour_spec, weekday_spec = fields

    minute_set = _parse_field(minute_spec, 0, 59)
    hour_set = _parse_field(hour_spec, 0, 23)
    weekday_set = _parse_field(weekday_spec, 0, 6)

    return minute_set, hour_set, weekday_set


def _parse_field(spec: str, min_val: int, max_val: int) -> set[int]:
    terms = spec.split(',')
    result = set()
    for term in terms:
        if not term:
            raise ValueError("Empty term")
        result |= _parse_term(term, min_val, max_val)
    return result


def _parse_term(term: str, min_val: int, max_val: int) -> set[int]:
    parts = term.split('/')
    if len(parts) > 2:
        raise ValueError("More than one '/'")

    if len(parts) == 1:
        base = parts[0]
        step = 1
    else:
        base = parts[0]
        step = _parse_int(parts[1])
        if step == 0:
            raise ValueError("Step of 0")

    if base == '*':
        start = min_val
        end = max_val
    elif '-' in base:
        parts_base = base.split('-')
        if len(parts_base) != 2:
            raise ValueError("Invalid range")
        n, m = _parse_int(parts_base[0]), _parse_int(parts_base[1])
        if n > m:
            raise ValueError("N > M")
        if n < min_val or m > max_val:
            raise ValueError("Value above MAX")
        start = n
        end = m
    else:
        start = _parse_int(base)
        end = max_val
        if start < min_val or start > max_val:
            raise ValueError("Value above MAX")

    result = set()
    for v in range(start, end + 1, step):
        if v > max_val:
            raise ValueError("Value above MAX")
        result.add(v)

    return result


def _parse_int(s: str) -> int:
    if not s:
        raise ValueError("Empty string")
    if s[0] in '+-':
        raise ValueError("Sign not allowed")
    if not s.isdigit():
        raise ValueError("Non-digit character")
    return int(s)
