import heapq
from collections import defaultdict


def ferry_plan(routes: list[tuple[str, str, int, int, int]], src: str, dst: str, t0: int) -> tuple[int, int] | None:
    if src == dst:
        return (t0, 0)

    # Build adjacency list: port -> list of (dest, first, every, duration)
    adj: dict[str, list[tuple[str, int, int, int]]]] = defaultdict(list)
    for a, b, first, every, duration in routes:
        if a == b:
            continue
        adj[a].append((b, first, every, duration))

    # Priority queue: (arrival_time, num_ferries, port)
    pq: list[tuple[int, int, str]] = [(t0, 0, src)]

    # Track seen (port, arrival_time) pairs to avoid redundant processing
    seen: set[tuple[str, int]] = set()
    seen.add((src, t0))

    while pq:
        t, f, port = heapq.heappop(pq)

        if port == dst:
            return (t, f)

        # Try all outgoing ferries from this port
        for dest, first, every, duration in adj[port]:
            # Find the earliest departure time >= t
            if first >= t:
                dep_time = first
            else:
                # We need smallest k >= 0 such that first + k*every >= t
                # k >= (t - first) / every, so k = ceil((t - first) / every)
                k = (t - first + every - 1) // every
                dep_time = first + k * every

            arr_time = dep_time + duration
            new_f = f + 1

            if (dest, arr_time) not in seen:
                seen.add((dest, arr_time))
                heapq.heappush(pq, (arr_time, new_f, dest))

    return None
